    if number.startswith(" ") or number.endswith(" ") or "  " in number:
        return False

    digits = number.replace(" ", "")
    if len(digits) < 2:
        return False
    if any(ch < "0" or ch > "9" for ch in digits):
        return False

    total = 0
    for index, ch in enumerate(reversed(digits)):
        value = ord(ch) - ord("0")
